preConditionHook:
// Exit the open position the moment the OPPOSITE side's bar count reaches
// countTarget. Brooks: 'if you ever buy early, always get out and even
// reverse if the market triggers a low 2 or 3 short', and mirrored for a
// short caught by a high 2 or 3. The 'even reverse' half is the engine's own
// reversal behaviour, not a condition, so it is not carried here.
//
// Kept as its own rule rather than a placement of HighLowBarCount because it
// reads the OPPOSITE side's counter -- which a mirrored Entry placement
// cannot supply -- and because it is an Exit: the long condition closes a
// LONG, and what it watches is the low count.
//
// THE COUNTER IS THE SETTLED ONE (Ranges ch17, R17-01), inlined here as
// everywhere -- see HighLowBarCount for the full commentary. The advance flag
// is deliberately not carried: the count is an equality against countTarget,
// which first becomes true on the advancing bar, and for an exit there is
// nothing to gain from firing on that bar only.
//
// ctx.MarketPosition() is the measured accessor (+1 / 0 / -1); it is read in
// the condition, exactly as EasyLanguage's MarketPosition is.
priorHigh = high[1];
priorLow = low[1];
for (int i = 2; i <= (int)resetLookback; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
if (el_gt(close[0], priorHigh)) {
    highCount = 0;
} else {
    if (el_lt(low[0], minLowSince)) minLowSince = low[0];
    if (el_gt(high[0], high[1]) && (highCount == 0 || el_lt(minLowSince, signalLow))) {
        highCount = highCount + 1;
        if (highCount > 4) highCount = 4;
        signalLow = low[0];
        minLowSince = low[0];
    }
}
if (el_lt(close[0], priorLow)) {
    lowCount = 0;
} else {
    if (el_gt(high[0], maxHighSince)) maxHighSince = high[0];
    if (el_lt(low[0], low[1]) && (lowCount == 0 || el_gt(maxHighSince, signalHigh))) {
        lowCount = lowCount + 1;
        if (lowCount > 4) lowCount = 4;
        signalHigh = high[0];
        maxHighSince = high[0];
    }
}
